create table if not exists public.google_calendar_connections (user_id uuid primary key references auth.users(id) on delete cascade,access_token_encrypted text not null,refresh_token_encrypted text,expires_at timestamptz not null,scope text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.google_calendar_connections enable row level security;drop policy if exists "Users manage own calendar connection" on public.google_calendar_connections;create policy "Users manage own calendar connection" on public.google_calendar_connections for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
